Class Pedido
  Private Define productos As Vector<String>;

  Method Constructor()
    This.productos <- vector();
  EndMethod

  Method Agregar(producto As String)
    This.productos.append(producto);
  EndMethod

  Method Ticket() As String
    Return join(This.productos, ", ");
  EndMethod

  Method Duplicar() As Pedido
    Define duplicado As Pedido <- New Pedido();
    For Each producto In This.productos Do
      duplicado.Agregar(producto);
    EndFor
    Return duplicado;
  EndMethod
EndClass

Algorithm Pedidos
  Define primero, segundo, extra As String;
  Read primero;
  Read segundo;
  Read extra;
  Define pedido As Pedido <- New Pedido();
  pedido.Agregar(primero);
  pedido.Agregar(segundo);
  Define copia As Pedido <- pedido;
  copia.Agregar(extra);
  Write "Original: ", pedido.Ticket();
  Write "Copia: ", copia.Ticket();
EndAlgorithm

